from rich.pretty import Pretty

class CustomClass:
    def __init__(self, items):
        self.items = items
    def __len__(self):
        return len(self.items)
    def __getitem__(self, index):
        return self.items[index]
    def __iter__(self):
        return iter(self.items)
    def __eq__(self, other):
        return True  # Always returns True, mimicking the issue description

def test_custom_class_pretty_print():
    # Case 1: Custom class with items but behaves "truthy" or "falsy"
    # The issue was that 'elif obj:' might fail or behave weirdly if __eq__ is overridden
    obj = CustomClass([1, 2, 3])
    pretty = Pretty(obj)
    repr_val = repr(pretty)
    assert "[1, 2, 3]" in repr_val or "CustomClass" in repr_val

    # Case 2: Custom class that is empty
    obj_empty = CustomClass([])
    pretty_empty = Pretty(obj_empty)
    repr_empty = repr(pretty_empty)
    # Should render as empty braces, not as if it had content
    # Since it's a custom class, it depends on how it's handled.
    # But it definitely shouldn't enter the 'elif len(obj) > 0' block.

if __name__ == "__main__":
    test_custom_class_pretty_print()
    print("Test passed!")
